package com.javacodingagent.api.task;
import com.javacodingagent.api.repository.InMemoryRepositoryService; import com.javacodingagent.api.trace.TaskEventBroker; import com.javacodingagent.common.domain.*; import com.javacodingagent.core.CodingAgentEngine; import java.util.*; import java.util.concurrent.*;
/** Async application service with one writer per repository. */
public class TaskOrchestrator { private final InMemoryTaskService tasks; private final InMemoryRepositoryService repositories; private final CodingAgentEngine engine; private final TaskEventBroker events; private final Executor executor; private final Map<Long, Semaphore> locks = new ConcurrentHashMap<>();
 public TaskOrchestrator(InMemoryTaskService tasks, InMemoryRepositoryService repositories, CodingAgentEngine engine, TaskEventBroker events, Executor executor) { this.tasks = tasks; this.repositories = repositories; this.engine = engine; this.events = events; this.executor = executor; }
 public TaskView submit(CreateTaskRequest request) { var repository = repositories.find(request.repositoryId()).orElseThrow(() -> new IllegalArgumentException("Repository not found")); TaskView task = tasks.create(request); events.publish(task.taskId(), "TASK_STARTED", task); CompletableFuture.runAsync(() -> { Semaphore lock = locks.computeIfAbsent(repository.id(), ignored -> new Semaphore(1)); boolean acquired = false; try { acquired = lock.tryAcquire(1, TimeUnit.SECONDS); if (!acquired) { tasks.update(task.taskId(), AgentTaskStatus.WAITING_CONFIRMATION); events.publish(task.taskId(), "WAITING_CONFIRMATION", "Repository is locked by another task"); return; } var context = new AgentExecutionContext(); context.setTaskId(task.taskId()); context.setTraceId(task.traceId()); context.setSessionId(UUID.randomUUID().toString()); context.setRepositoryPath(repository.workspacePath()); var result = engine.execute(context, task.requirement(), task.maxRepairCount()); tasks.update(task.taskId(), result.status()); events.publish(task.taskId(), result.status() == AgentTaskStatus.SUCCEEDED ? "TASK_SUCCEEDED" : "TASK_FAILED", result); } catch (Exception e) { tasks.update(task.taskId(), AgentTaskStatus.FAILED); events.publish(task.taskId(), "TASK_FAILED", e.getMessage()); } finally { if (acquired) lock.release(); } }, executor); return task; }
}
